    int digitC_val   = (pos >= lenC) ? -1 : (C[lenC - 1 - pos] == '?' ? -1 : C[lenC - 1 - pos] - '0');

    for (int da = digitA_start; da <= digitA_end; da++) {
        if (pos == lenA - 1 && da == 0 && lenA > 1) continue; // leading zero check
        for (int db = digitB_start; db <= digitB_end; db++) {
            if (pos == lenB - 1 && db == 0 && lenB > 1) continue;
            int sum = da + db + carry;
            int digitC = sum % 10;
            int newCarry = sum / 10;

            if (digitC_val != -1 && digitC != digitC_val) continue;
            if (pos == lenC - 1 && digitC == 0 && lenC > 1) continue; // leading zero for C

