#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL
#define MAXL 100005

static char A[MAXL], B[MAXL], Cc[MAXL];
static int ra[MAXL], rb[MAXL], rc[MAXL];

int main(void) {
    while (scanf("%s %s %s", A, B, Cc) == 3) {
        int la = (int)strlen(A);
        int lb = (int)strlen(B);
        int lc = (int)strlen(Cc);

        for (int i = 0; i < la; i++) ra[i] = A[la - 1 - i];
        for (int i = 0; i < lb; i++) rb[i] = B[lb - 1 - i];
        for (int i = 0; i < lc; i++) rc[i] = Cc[lc - 1 - i];

        long long dp0 = 1, dp1 = 0; /* carry 0 / 1 before current digit */

        int maxl = la;
        if (lb > maxl) maxl = lb;
        if (lc > maxl) maxl = lc;

        for (int pos = 0; pos < maxl; pos++) {
            long long ndp0 = 0, ndp1 = 0;

            int hasA = (pos < la);
            int hasB = (pos < lb);
            int hasC = (pos < lc);

            /* If one number has no digit here, treat as fixed absent digit.
               Since lengths are fixed, absent positions cannot receive digits. */
            for (int carry = 0; carry <= 1; carry++) {
                long long cur = (carry == 0 ? dp0 : dp1);
                if (!cur) continue;

                for (int da = 0; da <= 9; da++) {
                    if (!hasA) {
                        if (da != 0) continue;
                    } else {
                        char ch = (char)ra[pos];
                        if (ch != '?' && da != ch - '0') continue;
                        if (pos == la - 1 && la > 1 && da == 0) continue; /* leading zero */
                    }

                    for (int db = 0; db <= 9; db++) {
                        if (!hasB) {
                            if (db != 0) continue;
                        } else {
                            char ch = (char)rb[pos];
                            if (ch != '?' && db != ch - '0') continue;
                            if (pos == lb - 1 && lb > 1 && db == 0) continue; /* leading zero */
                        }

                        int sum = da + db + carry;
                        int dc = sum % 10;
                        int ncarry = sum / 10;

                        if (!hasC) {
                            if (dc != 0) continue;
                        } else {
                            char ch = (char)rc[pos];
                            if (ch != '?' && dc != ch - '0') continue;
                            if (pos == lc - 1 && lc > 1 && dc == 0) continue; /* leading zero */
                        }

                        if (ncarry == 0) {
                            ndp0 += cur;
                            if (ndp0 >= MOD) ndp0 %= MOD;
                        } else {
                            ndp1 += cur;
                            if (ndp1 >= MOD) ndp1 %= MOD;
                        }
                    }
                }
            }

            dp0 = ndp0 % MOD;
            dp1 = ndp1 % MOD;
        }

        /* No extra carry allowed beyond the fixed length of C */
        printf("%lld\n", dp0 % MOD);
    }

    return 0;
}

