            vector<long long> ndp(2, 0);
            // Get possible digits for a, b, c at column i
            auto getDigits = [&](const string& s, int len, int pos) -> pair<int,int> {
                // returns (lo, hi) range, or fixed digit as (d, d)
                if (pos >= len) return {0, 0}; // beyond length, fixed 0
                char ch = s[pos];
                bool isLeading = (pos == len - 1) && (len > 1);
                if (ch == '?') {
                    return {isLeading ? 1 : 0, 9};
                } else {
                    int d = ch - '0';
                    return {d, d};
                }
            };
            auto [alo, ahi] = getDigits(A, la, i);
            auto [blo, bhi] = getDigits(B, lb, i);
            auto [clo, chi] = getDigits(C, lc, i);

