                for (int a = alo; a <= ahi; a++)
                for (int b = blo; b <= bhi; b++) {
                    int sum = a + b + carry;
                    int c = sum % 10;
                    int ncarry = sum / 10;
                    if (c >= clo && c <= chi) {
                        ndp[ncarry] = (ndp[ncarry] + dp[carry]) % MOD;
                    }
                }
            }
            dp = ndp;
