static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<array<string,3>> tests;
    string A, B, C;

    // Read datasets until EOF.
    // Each dataset consists of three strings: A B C
    while (cin >> A >> B >> C) {
        tests.push_back({A, B, C});
    }

    for (auto &tc : tests) {
        A = tc[0];
        B = tc[1];
        C = tc[2];

        int nA = (int)A.size();
        int nB = (int)B.size();
        int nC = (int)C.size();
        int L = max({nA, nB, nC});

        // Reverse for least-significant-digit-first processing
        string RA = string(A.rbegin(), A.rend());
        string RB = string(B.rbegin(), B.rend());
        string RC = string(C.rbegin(), C.rend());

        auto getChar = [&](const string &R, int pos) -> char {
            if (pos < (int)R.size()) return R[pos];
            return '#'; // no digit at this position
        };

        // dp[pos][carry] = number of ways for positions [0..pos-1]
        long long dp[2] = {1, 0}, ndp[2] = {0, 0};

        for (int pos = 0; pos < L; ++pos) {
            ndp[0] = ndp[1] = 0;

            char ca = getChar(RA, pos);
            char cb = getChar(RB, pos);
            char cc = getChar(RC, pos);

            for (int carry = 0; carry <= 1; ++carry) {
                long long cur = dp[carry];
                if (!cur) continue;

                vector<int> da, db, dc;

                auto fillDigits = [&](char ch, int len, vector<int> &vec) {
                    if (ch == '#') return;
                    if (ch == '?') {
                        int origPos = len - 1 - pos; // position in original string
                        bool leading = (origPos == 0 && len > 1);
                        for (int d = 0; d <= 9; ++d) {
                            if (leading && d == 0) continue;
                            vec.push_back(d);
                        }
                    } else {
                        vec.push_back(ch - '0');
                    }
                };

                fillDigits(ca, nA, da);
                fillDigits(cb, nB, db);
                fillDigits(cc, nC, dc);

                // If a number has no digit here, it contributes only 0 and cannot be assigned.
                if (ca == '#') da.push_back(0);
                if (cb == '#') db.push_back(0);
                if (cc == '#') dc.push_back(0);

                // Enumerate possible digits
                for (int x : da) {
                    for (int y : db) {
                        int sum = x + y + carry;
                        int z = sum % 10;
                        int ncarry = sum / 10;

                        // Check whether z is allowed for C at this position
                        for (int w : dc) {
                            if (w == z) {
                                ndp[ncarry] += cur;
                                if (ndp[ncarry] >= MOD) ndp[ncarry] -= MOD;
                            }
                        }
                    }
                }
            }

            dp[0] = ndp[0];
            dp[1] = ndp[1];
        }

        // After all positions processed, no carry must remain,
        // and also numbers cannot have extra digits beyond L since L is max length.
        cout << dp[0] % MOD << '\n';
    }

    return 0;
}

