public class Main {
    static final int MOD = 1_000_000_007;
    static String A, B, C;
    static int n;
    static long[][][] dp;
    static boolean[] leadingA, leadingB, leadingC;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            String a = sc.next();
            String b = sc.next();
            String c = sc.next();
            System.out.println(solve(a, b, c));
        }
        sc.close();
    }

    static long solve(String a, String b, String c) {
        A = a; B = b; C = c;
        n = Math.max(Math.max(a.length(), b.length()), c.length());

        // Pad with leading zeros for uniform length
        A = padLeft(a, n);
        B = padLeft(b, n);
        C = padLeft(c, n);

        // Track if each position is the leading digit of the original number
        leadingA = new boolean[n];
        leadingB = new boolean[n];
        leadingC = new boolean[n];
        int lenA = a.length(), lenB = b.length(), lenC = c.length();
        for (int i = 0; i < n; i++) {
            leadingA[i] = (n - i == lenA) && lenA > 1;
            leadingB[i] = (n - i == lenB) && lenB > 1;
            leadingC[i] = (n - i == lenC) && lenC > 1;
        }

        dp = new long[n + 1][2][2];
        for (int i = 0; i <= n; i++)
            for (int j = 0; j < 2; j++)
                Arrays.fill(dp[i][j], -1);

        return dfs(0, 0, 0);
    }

    static String padLeft(String s, int len) {
        StringBuilder sb = new StringBuilder();
        while (sb.length() + s.length() < len) sb.append('0');
        sb.append(s);
        return sb.toString();
    }

    static long dfs(int pos, int carry, int started) {
        if (pos == n) {
            return (carry == 0 && started == 0) ? 1 : 0;
        }
        if (dp[pos][carry][started] != -1) return dp[pos][carry][started];
        long res = 0;
        char ca = A.charAt(pos);
        char cb = B.charAt(pos);
        char cc = C.charAt(pos);

        for (int da = 0; da <= 9; da++) {
            if (ca != '?' && da != ca - '0') continue;
            if (leadingA[pos] && da == 0) continue;
            for (int db = 0; db <= 9; db++) {
                if (cb != '?' && db != cb - '0') continue;
                if (leadingB[pos] && db == 0) continue;
                int sum = da + db + carry;
                int dc = sum % 10;
                int newCarry = sum / 10;
                if (cc != '?' && dc != cc - '0') continue;
                if (leadingC[pos] && dc == 0) continue;
                res += dfs(pos + 1, newCarry, 0);
                if (res >= MOD) res -= MOD;
            }
        }
        return dp[pos][carry][started] = res;
    }
}

