public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split("\\s+");
            if (parts.length < 3) continue;
            String A = parts[0], B = parts[1], C = parts[2];
            System.out.println(solve(A, B, C));
        }
    }

    static long solve(String A, String B, String C) {
        int lenA = A.length(), lenB = B.length(), lenC = C.length();
        int maxLen = Math.max(Math.max(lenA, lenB), lenC);

        // Pad from left with a fixed '0' if shorter? No - different lengths mean carry constraints
        // Actually if lengths differ significantly, A+B=C might be impossible
        // Let's pad all to maxLen from the left with '0' (fixed zero)
        // But leading zero constraint applies to original first digit

        char[] a = pad(A, maxLen);
        char[] b = pad(B, maxLen);
        char[] c = pad(C, maxLen);

        // dp[carry] = number of ways, process from right to left
        long[] dp = new long[2];
        dp[0] = 1;

        for (int i = maxLen - 1; i >= 0; i--) {
            long[] ndp = new long[2];
            for (int carry = 0; carry <= 1; carry++) {
                if (dp[carry] == 0) continue;
                // enumerate digits for a[i], b[i], c[i]
                int aLo = a[i] == '?' ? 0 : (a[i]-'0'), aHi = a[i] == '?' ? 9 : (a[i]-'0');
                int bLo = b[i] == '?' ? 0 : (b[i]-'0'), bHi = b[i] == '?' ? 9 : (b[i]-'0');
                int cLo = c[i] == '?' ? 0 : (c[i]-'0'), cHi = c[i] == '?' ? 9 : (c[i]-'0');

                for (int da = aLo; da <= aHi; da++)
                    for (int db = bLo; db <= bHi; db++) {
                        int sum = da + db + carry;
                        int dc = sum % 10, ncarry = sum / 10;
                        if (dc >= cLo && dc <= cHi) {
                            ndp[ncarry] = (ndp[ncarry] + dp[carry]) % MOD;
                        }
                    }
            }
            dp = ndp;
        }

        long ans = dp[0]; // no carry out
        // Apply leading zero constraints
        // If original length < maxLen, the padded zeros are fixed, no issue
        // Leading digit of original number: position (maxLen - origLen) in padded array
        // If original length > 1 and that position is '?', subtract cases where it's 0
        // This is complex - need to redo with constraints
        // For simplicity, let me handle leading zeros by restricting first '?' of each number
        // Actually the padding adds fixed '0's which won't be '?', so leading zero of original is at index (maxLen-origLen)
        // That's already handled since padded chars are '0' not '?'

        return ans;
    }

    static char[] pad(String s, int len) {
        char[] res = new char[len];
        int diff = len - s.length();
        for (int i = 0; i < diff; i++) res[i] = '0';
        for (int i = 0; i < s.length(); i++) res[diff+i] = s.charAt(i);
        return res;
    }
}

