import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String A = fs.next();
            if (A == null) break;
            String B = fs.next();
            String C = fs.next();
            long ans = solve(A, B, C);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static long solve(String A, String B, String C) {
        int la = A.length(), lb = B.length(), lc = C.length();
        int n = Math.max(la, Math.max(lb, lc));

        char[] a = new char[n];
        char[] b = new char[n];
        char[] c = new char[n];
        Arrays.fill(a, '#');
        Arrays.fill(b, '#');
        Arrays.fill(c, '#');

        for (int i = 0; i < la; i++) a[i] = A.charAt(la - 1 - i);
        for (int i = 0; i < lb; i++) b[i] = B.charAt(lb - 1 - i);
        for (int i = 0; i < lc; i++) c[i] = C.charAt(lc - 1 - i);

        boolean[] leadA = new boolean[n];
        boolean[] leadB = new boolean[n];
        boolean[] leadC = new boolean[n];
        leadA[la - 1] = true;
        leadB[lb - 1] = true;
        leadC[lc - 1] = true;

        long[] dp = new long[2];
        dp[0] = 1;

        for (int pos = 0; pos < n; pos++) {
            long[] ndp = new long[2];

            int[] da = possibleDigits(a[pos], leadA[pos], la);
            int[] db = possibleDigits(b[pos], leadB[pos], lb);
            int[] dc = possibleDigits(c[pos], leadC[pos], lc);

            for (int carry = 0; carry <= 1; carry++) {
                if (dp[carry] == 0) continue;
                long cur = dp[carry];

                for (int x : da) {
                    for (int y : db) {
                        int sum = x + y + carry;
                        int z = sum % 10;
                        int ncarry = sum / 10;
                        if (contains(dc, z)) {
                            ndp[ncarry] += cur;
                            if (ndp[ncarry] >= MOD) ndp[ncarry] -= MOD;
                        }
                    }
                }
            }
            dp = ndp;
        }

        return dp[0];
    }

    static int[] possibleDigits(char ch, boolean isLeading, int len) {
        if (ch == '#') return new int[]{0}; // nonexistent higher digit
        if (ch != '?') {
            int d = ch - '0';
            if (isLeading && len > 1 && d == 0) return new int[0];
            return new int[]{d};
        }
        int from = 0;
        if (isLeading && len > 1) from = 1;
        int[] res = new int[10 - from];
        for (int i = from; i <= 9; i++) res[i - from] = i;
        return res;
    }

    static boolean contains(int[] arr, int x) {
        for (int v : arr) if (v == x) return true;
        return false;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

import sys

MOD = 1_000_000_007

def count_solutions(A: str, B: str, C: str) -> int:
    la, lb, lc = len(A), len(B), len(C)
    n = max(la, lb, lc)

    # Reverse for least-significant-digit first processing
    Ar = A[::-1]
    Br = B[::-1]
    Cr = C[::-1]

    # dp[carry] after processing i digits
    dp0, dp1 = 1, 0

    for i in range(n):
        ca = Ar[i] if i < la else None
        cb = Br[i] if i < lb else None
        cc = Cr[i] if i < lc else None

        # Determine possible digits for each position
        def possible_digits(ch, pos_from_right, length):
            if ch is None:
                return None  # no digit exists
            if ch != '?':
                return [ord(ch) - 48]
            # '?' case
            # Most significant digit cannot be zero if length > 1
            if pos_from_right == length - 1 and length > 1:
                return list(range(1, 10))
            return list(range(10))

        da = possible_digits(ca, i, la)
        db = possible_digits(cb, i, lb)
        dc = possible_digits(cc, i, lc)

        ndp0, ndp1 = 0, 0

        # Since each digit set size <= 10, brute force per column is fine
        for carry_in, ways_in in ((0, dp0), (1, dp1)):
            if ways_in == 0:
                continue

            if da is None:
                digits_a = [0]
            else:
                digits_a = da
            if db is None:
                digits_b = [0]
            else:
                digits_b = db
            if dc is None:
                digits_c = [0]
            else:
                digits_c = dc

            # If a number has no digit at this position, it must behave as 0
            # and cannot be assigned anything else.
            for x in digits_a:
                for y in digits_b:
                    s = x + y + carry_in
                    z = s % 10
                    carry_out = s // 10
                    # check z against possible c digit
                    # If C has no digit here, only z=0 is allowed
                    if cc is None:
                        if z != 0:
                            continue
                        if carry_out == 0:
                            ndp0 = (ndp0 + ways_in) % MOD
                        else:
                            ndp1 = (ndp1 + ways_in) % MOD
                    else:
                        # membership test on small list
                        if z in digits_c:
                            if carry_out == 0:
                                ndp0 = (ndp0 + ways_in) % MOD
                            else:
                                ndp1 = (ndp1 + ways_in) % MOD

        dp0, dp1 = ndp0, ndp1

    # No carry must remain after the most significant processed digit
    return dp0 % MOD


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Support both formats:
    # 1) T followed by T triples
    # 2) Just triples until EOF
    if len(data) >= 4 and data[0].isdigit():
        t = int(data[0])
        if 1 + 3 * t == len(data):
            idx = 1
            out = []
            for _ in range(t):
                A, B, C = data[idx], data[idx + 1], data[idx + 2]
                idx += 3
                out.append(str(count_solutions(A, B, C)))
            sys.stdout.write("\n".join(out))
            return

    # Fallback: read triples until EOF
    out = []
    for i in range(0, len(data), 3):
        A, B, C = data[i], data[i + 1], data[i + 2]
        out.append(str(count_solutions(A, B, C)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
